package com.example.fdstatement;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import com.example.fdshared.DomainEvent;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import java.math.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
@SpringBootTest @ActiveProfiles("test") @AutoConfigureMockMvc class StatementIntegrationTest {
 @Autowired StatementService service;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 @BeforeEach void reset(){jdbc.update("DELETE FROM consumed_events");jdbc.update("DELETE FROM fd_statements");}
 DomainEvent event(String type,int seconds){var d=new LinkedHashMap<String,Object>();d.put("fdAccountNo","FD001");d.put("customerId","CUST001");d.put("businessDate","2026-01-01");d.put("currency","INR");d.put("openingBalance",10000);d.put("closingBalance",10000);d.put("interestAccrued",type.equals("InterestAccrued")?10:0);d.put("interestCapitalized",0);d.put("interestPaid",type.equals("InterestPaid")?10:0);d.put("outstandingInterest",type.equals("InterestPaid")?0:10);return new DomainEvent(1,UUID.randomUUID().toString(),type,Instant.parse("2026-01-01T00:00:00Z").plusSeconds(seconds),"FD001",mapper.valueToTree(d));}
 @Test void duplicateEventIgnored(){var e=event("InterestAccrued",1);service.project(e);service.project(e);assertThat(jdbc.queryForObject("SELECT interest_accrued FROM fd_statements",BigDecimal.class)).isEqualByComparingTo("10");}
 @Test void sameDatePayoutMerges(){service.project(event("InterestAccrued",1));service.project(event("InterestPaid",2));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM fd_statements",Integer.class)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT interest_paid FROM fd_statements",BigDecimal.class)).isEqualByComparingTo("10");assertThat(jdbc.queryForObject("SELECT outstanding_interest FROM fd_statements",BigDecimal.class)).isZero();}
 @Test void outOfOrderSnapshotsPreserved(){service.project(event("InterestPaid",2));service.project(event("InterestAccrued",1));assertThat(jdbc.queryForObject("SELECT outstanding_interest FROM fd_statements",BigDecimal.class)).isZero();assertThat(jdbc.queryForObject("SELECT interest_accrued FROM fd_statements",BigDecimal.class)).isEqualByComparingTo("10");}
 @Test void invalidEventRollsBack(){var e=event("InterestAccrued",1);((com.fasterxml.jackson.databind.node.ObjectNode)e.data()).remove("closingBalance");assertThatThrownBy(()->service.project(e)).isInstanceOf(IllegalArgumentException.class);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM consumed_events",Integer.class)).isZero();}
 @Test void statementReadRequiresLogin()throws Exception{mvc.perform(get("/api/statements/FD001")).andExpect(status().isUnauthorized());mvc.perform(get("/api/statements/FD001").with(httpBasic("officer1","officer123"))).andExpect(status().isOk());}
 // Jackson 3 would write a SQL DATE as a UTC instant (2025-12-31T18:30:00.000Z in IST); the API must keep the plain date.
 @Test void statementDateIsPlainDate()throws Exception{service.project(event("InterestAccrued",1));mvc.perform(get("/api/statements/FD001").with(httpBasic("admin1","admin123"))).andExpect(status().isOk()).andExpect(jsonPath("$[0].statement_date").value("2026-01-01"));}
}
